// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 ts, address actor) public {
        vm.assume(actor != address(c) && actor != address(this) && actor != address(0));
        ts = bound(ts, 1, type(uint256).max - 2);

        vm.deal(actor, 20 ether);
        vm.warp(ts);
        vm.roll(1); // block.number % 15 != 0, so no payout branch interferes

        vm.prank(actor);
        (bool ok1,) = address(c).call{value: 10 ether}("");

        // second call at the SAME timestamp: must revert because pastBlockTime == ts + 1 > ts
        vm.prank(actor);
        (bool ok2,) = address(c).call{value: 10 ether}("");

        assertTrue(ok1 && !ok2);
    }
}
